import{_ as s,l as i,o as a,c as l,v as t,p as n,x as r,d as E,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"MOESI 与 MESIF","description":"","frontmatter":{"title":"MOESI 与 MESIF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/moesi-mesif.md","filePath":"cs/moesi-mesif.md","lastUpdated":1789023840000}'),S={name:"cs/moesi-mesif.md"};function h(p,e,m,B,M,A){const o=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="moesi-与-mesif" tabindex="-1">MOESI 与 MESIF <a class="header-anchor" href="#moesi-与-mesif" aria-label="Permalink to &quot;MOESI 与 MESIF&quot;">​</a></h1><div class="epigraph"><p>脏数据不必先写回 LLC 再给请求者：Owned 允许共享脏副本并指定一个责任人；Forward 指定谁来响应共享读，避免所有 S 一起抢答。</p><footer>—— 据 Sweazey and Smith；AMD64 对 MOESI 的描述；Intel 对 MESIF 的描述 整理</footer></div><p><a href="/cs/hugepage-tlb-reach">上一课</a> 放大单核翻译。多核上 <a href="/cs/mesi-protocol">MESI</a> 已经保证至多一份 M。脏行被他核读时，MESI 通常写回再双方变 S——LLC 与内存带宽被打满。本课不重画四态。缺口是<strong>O（Owned）与 F（Forward）：共享时仍能指出数据从哪来、脏责任在谁。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核 A 持有 M，核 B 读同一行：数据在 A 的 L1 里最新。若必须先写到 LLC，延迟和功耗都高。MOESI 加 Owned：脏且可共享，O 核负责将来写回，其他核为 S。MESIF 加 Forward：干净共享时指定一个 F 核响应后续读，避免监听风暴里所有 S 重复提供。缺口不是分区，而是<strong>五态机减少写回与重复响应。</strong></p><p><span class="marginnote">MOESI 常见于 AMD 窥探/Infinity。MESIF 用于 Intel QPI/UPI：F 是干净共享的指定转发者。二者都不是内存模型，只是副本放置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MOESI：M 被他核读 → 提供者变 O，请求者变 S，数据直接 cache-to-cache，内存可暂不更新。O 被写或替换则写回。MESIF：S 集合里指定 F；后续共享读由 F 提供，其余 S 沉默。</p>',8)),(a(),n(d,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22M%20%E8%84%8F%E7%8B%AC%E6%9C%89%22%5D%20--%3E%7C%22%E4%BB%96%E6%A0%B8%E8%AF%BB%22%7C%20O%5B%22O%20%E8%84%8F%E5%85%B1%E4%BA%AB%E8%B4%A3%E4%BB%BB%E4%BA%BA%22%5D%0A%20%20O%20--%3E%20S%5B%22%E5%85%B6%E4%BB%96%E6%A0%B8%20S%22%5D%0A%20%20S2%5B%22%E5%B9%B2%E5%87%80%E5%85%B1%E4%BA%AB%22%5D%20--%3E%20F%5B%22F%20%E6%8C%87%E5%AE%9A%E8%BD%AC%E5%8F%91%22%5D%0A%20%20F%20--%3E%7C%22%E4%BB%96%E6%A0%B8%E8%AF%BB%22%7C%20F%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不变式仍是：可写副本至多一份（M 或即将升级者）；脏至多一份责任人（M 或 O）。<a href="/cs/retire-precise-exception">退休</a> 的 store 仍只有提交后才进入这些状态。cache-to-cache 把 <a href="/cs/mlp-memory-parallelism">MLP</a> 的 miss 延迟从 DRAM 变成核间互联，后课 socket 互连会再放大这段。</p><p>伪共享不因 O/F 消失：行粒度还在，只是颠簸走核间而不是 DRAM。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把目录里的「owner 指针」写完，下一课目录扩展性会把窥探广播换掉。也不把 ARM 的 MOESI 变体逐比特对照。原子操作如何在这些态上锁 cache 行，是后课。</p><p>后课默认：共享脏可以不立即写内存；指定转发者减少重复应答。核数再涨，广播监听本身不可扩展。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MOESI 的 O 允许共享脏；MESIF 的 F 指定干净共享的响应者。</li><li>协议管副本，不管多地址顺序。</li><li>目录如何避免广播，是下一课扩展性。</li><li>出处：Sweazey and Smith；AMD MOESI；Intel MESIF。</li></ul>',8))])}const f=s(S,[["render",h]]);export{_ as __pageData,f as default};
